import { randomUUID } from "node:crypto";
import { mkdir, open, readFile, rename, rm, stat, writeFile } from "node:fs/promises";
import { homedir } from "node:os";
import path from "node:path";
import { activateStateScope, getState, replaceState } from "../todo/state/store.js";
import { EMPTY_STATE, type TaskState } from "../todo/state/state.js";
import { isTaskDetails } from "../todo/state/replay.js";

const LOCK_TIMEOUT_MS = 15_000;
const STALE_LOCK_MS = 120_000;

export interface HeadlessTodoSession {
	/** Opaque SHA-256/HMAC identity generated by the MCP host, not the raw chat ID. */
	key: string;
	/** Optional override for test harnesses; default is ~/.pi/headless-todos. */
	directory?: string;
}

function location(session: HeadlessTodoSession): string {
	if (!/^[a-f0-9]{64}$/.test(session.key)) throw new Error("Todo needs a stable, host-generated session key");
	return path.join(session.directory ?? path.join(homedir(), ".pi", "headless-todos"), `${session.key}.json`);
}

function isState(value: unknown): value is TaskState {
	if (!value || typeof value !== "object") return false;
	const record = value as Record<string, unknown>;
	return isTaskDetails(record) && Number.isSafeInteger(record.nextId) && (record.nextId as number) >= 1
		&& Array.isArray(record.tasks) && record.tasks.every((task: any) =>
			task && Number.isSafeInteger(task.id) && task.id > 0 && typeof task.subject === "string"
			&& ["pending", "in_progress", "deferred", "completed", "deleted"].includes(task.status));
}

async function acquireLock(file: string, signal: AbortSignal): Promise<() => Promise<void>> {
	const lock = `${file}.lock`;
	const started = Date.now();
	while (true) {
		signal.throwIfAborted();
		try {
			const handle = await open(lock, "wx", 0o600);
			await handle.close();
			return () => rm(lock, { force: true });
		} catch (error) {
			if ((error as NodeJS.ErrnoException).code !== "EEXIST") throw error;
			const info = await stat(lock).catch(() => undefined);
			if (info && Date.now() - info.mtimeMs > STALE_LOCK_MS) {
				await rm(lock, { force: true });
				continue;
			}
			if (Date.now() - started > LOCK_TIMEOUT_MS) throw new Error("Todo session is busy; retry the same request");
			await new Promise((resolve) => setTimeout(resolve, 35));
		}
	}
}

/**
 * The original Pix todo reducer/tool owns the actual semantics. Persist its
 * committed state per ChatGPT session because a one-request CLI cannot replay
 * a Pi JSONL branch. Cross-process locks prevent concurrent lost updates.
 */
export async function withHeadlessTodoSession<T>(
	session: HeadlessTodoSession,
	signal: AbortSignal,
	run: () => Promise<T>,
): Promise<T> {
	const file = location(session);
	await mkdir(path.dirname(file), { recursive: true, mode: 0o700 });
	const release = await acquireLock(file, signal);
	try {
		signal.throwIfAborted();
		let state: TaskState = { tasks: [], nextId: EMPTY_STATE.nextId };
		try {
			const stored: unknown = JSON.parse(await readFile(file, "utf8"));
			if (!isState(stored)) throw new Error("Invalid headless todo state");
			state = stored;
		} catch (error) {
			if ((error as NodeJS.ErrnoException).code !== "ENOENT") throw error;
		}
		activateStateScope(`id:${session.key}`);
		replaceState(state);
		const result = await run();
		const committed = getState();
		if (!isState(committed)) throw new Error("Pix todo committed an invalid state");
		const temporary = `${file}.${randomUUID()}.tmp`;
		try {
			await writeFile(temporary, `${JSON.stringify(committed)}\n`, { mode: 0o600, flag: "wx" });
			await rename(temporary, file);
		} finally {
			await rm(temporary, { force: true });
		}
		return result;
	} finally {
		await release();
	}
}
